Assuming React + `fetch` (no stack given). Debounce 300ms, abort stale requests:

```jsx
import { useState, useEffect } from "react";

function SearchBox() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);

  useEffect(() => {
    if (!query.trim()) { setResults([]); return; }
    const ctrl = new AbortController();
    const t = setTimeout(() => {
      fetch(`/api/search?q=${encodeURIComponent(query)}`, { signal: ctrl.signal })
        .then(r => r.json())
        .then(setResults)
        .catch(e => { if (e.name !== "AbortError") console.error(e); });
    }, 300);
    return () => { clearTimeout(t); ctrl.abort(); };
  }, [query]);

  return (
    <>
      <input value={query} onChange={e => setQuery(e.target.value)} />
      <ul>{results.map(r => <li key={r.id}>{r.name}</li>)}</ul>
    </>
  );
}
```

Cleanup runs on every keystroke → clears pending timer, aborts in-flight request. Debounce + no out-of-order responses overwriting newer results.

